mapper.select:
select *
from mmba_command_result
where 1 = 1

    and behavior_type = #{request.behaviorType}


    and req_id = #{request.reqId}


    and um = #{request.um}


    and target_value like concat('%', #{request.targetValue}, '%')


    and customer_tel like concat('%', #{request.customerTel}, '%')


    and friend_phone like concat('%', #{request.friendPhone}, '%')


    and process_status = #{request.processStatus}


    and result_status = #{request.resultStatus}


    and (
        req_id like concat('%', #{request.keyword}, '%')
        or target_value like concat('%', #{request.keyword}, '%')
        or customer_tel like concat('%', #{request.keyword}, '%')
        or friend_phone like concat('%', #{request.keyword}, '%')
        or rec_id like concat('%', #{request.keyword}, '%')
        or staff_name like concat('%', #{request.keyword}, '%')
    )

order by update_time desc
